blocks.source:
flowchart LR
  WD["1. Working Directory\n(Files on Disk)"] -->|"git add file"| SA["2. Staging Area / Index\n(Next Commit Draft)"]
  SA -->|"git commit -m '...'"| LR["3. Local Repository\n(Immutable History)"]
  LR -->|"git push"| RM["4. Remote Repository\n(origin on GitHub)"]
  RM -->|"git fetch"| LR
  RM -->|"git pull (fetch + integrate)"| WD

  classDef work fill:#f0f9ff,stroke:#0284c7,stroke-width:1.5px;
  classDef stage fill:#ede9fe,stroke:#6366f1,stroke-width:1.5px;
  classDef repo fill:#ecfdf5,stroke:#059669,stroke-width:2px;
  classDef remote fill:#fff7ed,stroke:#ea580c,stroke-width:1.5px;

  class WD work;
  class SA stage;
  class LR repo;
  class RM remote;

digraph GitDAG {
  rankdir=LR;
  node [fontname="Helvetica", shape=circle, style=filled, fillcolor="#f1f5f9", color="#475569", width=0.6];
  edge [fontname="Helvetica", fontsize=10];

  subgraph cluster_merge {
    label="3-Way Merge (Preserves Branch Topology)";
    style=rounded;
    color="#cbd5e1";
    C1 -> C2;
    C1 -> F1;
    F1 -> F2;
    C2 -> M;
    F2 -> M;
    M [fillcolor="#d1fae5", color="#059669", label="M\n(merge)"];
    F1 [fillcolor="#e0e7ff", color="#4f46e5"];
    F2 [fillcolor="#e0e7ff", color="#4f46e5"];
  }

  subgraph cluster_rebase {
    label="Rebase (Linear History, New Hashes)";
    style=rounded;
    color="#cbd5e1";
    R1 [label="C1"];
    R2 [label="C2"];
    RF1 [label="F1'", fillcolor="#ede9fe", color="#7c3aed"];
    RF2 [label="F2'", fillcolor="#ede9fe", color="#7c3aed"];
    R1 -> R2 -> RF1 -> RF2;
  }
}

flowchart TD
  Push["git push"] -->|"! [rejected] (fetch first)"| Pull["git pull (with pull.rebase = true)"]
  Pull --> Conflict{"Merge conflict?"}
  Conflict -->|"No"| PushOK["git push (succeeds)"]
  Conflict -->|"Yes"| Edit["Edit file & remove <<< === >>> markers"]
  Edit --> Add["git add resolved-file"]
  Add --> Cont["git rebase --continue"]
  Cont --> Conflict

  classDef err fill:#ffe4e6,stroke:#e11d48,stroke-width:1.5px;
  classDef act fill:#f0f9ff,stroke:#0284c7,stroke-width:1.5px;
  classDef ok fill:#ecfdf5,stroke:#059669,stroke-width:2px;

  class Push err;
  class Pull,Edit,Add,Cont act;
  class PushOK ok;
